create table if not exists public.packages (id uuid primary key default gen_random_uuid(), name text not null, destination text, duration text, price numeric(12,2) not null default 0, status text not null default 'Active', description text, created_at timestamptz not null default now());
create table if not exists public.hotels (id uuid primary key default gen_random_uuid(), name text not null, city text, country text, contact text, status text not null default 'Active', notes text, created_at timestamptz not null default now());
create table if not exists public.flight_records (id uuid primary key default gen_random_uuid(), customer_name text not null, route text, travel_date date, pnr text, status text not null default 'Requested', notes text, created_at timestamptz not null default now());
create table if not exists public.transport_jobs (id uuid primary key default gen_random_uuid(), customer_name text not null, vehicle_service text, pickup_date date, driver text, status text not null default 'Scheduled', notes text, created_at timestamptz not null default now());
create table if not exists public.visa_applications (id uuid primary key default gen_random_uuid(), applicant_name text not null, country text, visa_type text, submitted_date date, status text not null default 'Documents needed', document_notes text, created_at timestamptz not null default now());
create table if not exists public.tours (id uuid primary key default gen_random_uuid(), name text not null, destination text, start_date date, capacity integer not null default 0, status text not null default 'Planned', description text, created_at timestamptz not null default now());
DO $$ DECLARE t text; BEGIN FOREACH t IN ARRAY ARRAY['packages','hotels','flight_records','transport_jobs','visa_applications','tours'] LOOP EXECUTE format('alter table public.%I enable row level security',t); EXECUTE format('drop policy if exists %I on public.%I',t||'_staff_read',t); EXECUTE format('create policy %I on public.%I for select to authenticated using (public.is_crm_staff())',t||'_staff_read',t); EXECUTE format('drop policy if exists %I on public.%I',t||'_staff_write',t); EXECUTE format('create policy %I on public.%I for all to authenticated using (public.is_crm_staff() and public.current_user_role() in (''admin'',''manager'')) with check (public.is_crm_staff() and public.current_user_role() in (''admin'',''manager''))',t||'_staff_write',t); END LOOP; END $$;
